def reply(lang,text):
    current=_norm(text)
    if not current or lang not in DATA:return None
    for intent,(phrases,replies) in DATA[lang].items():
        norms=[_norm(p) for p in phrases]
        if current in norms:
            key=f"{lang}|{intent}|{current}".encode("utf-8")
            return replies[int(hashlib.sha256(key).hexdigest(),16)%len(replies)]
    return None
